const cartItemsContainer=document.getElementById("cart-items"),cartEmptyState=document.getElementById("cart-empty"),cartSummary=document.getElementById("cart-summary"),cartTotalAmount=document.getElementById("cart-total"),checkoutBtn=document.getElementById("checkout-btn");function getOptimizedImageUrl(t,e){try{const n=new URL(t),a=`${n.host}${n.pathname}${n.search}`;return`https://wsrv.nl/?url=${encodeURIComponent(a)}&w=${e}&fit=contain&output=webp&q=82`}catch(e){return t}}function getOptimizedImageSrcset(t,e){return e.map(e=>`${getOptimizedImageUrl(t,e)} ${e}w`).join(", ")}function getCart(){return JSON.parse(localStorage.getItem("cart"))||[]}function saveCart(t){localStorage.setItem("cart",JSON.stringify(t)),updateCartBadge()}function formatCurrency(t){return`$${t.toFixed(2)}`}function updateCartBadge(){const t=getCart().reduce((t,e)=>t+e.quantity,0),e=document.querySelector(".cart-badge");e&&(e.textContent=t,e.style.display=t>0?"flex":"none")}function calculateCartTotal(t){return t.reduce((t,e)=>t+(e.unitPrice||e.price)*e.quantity,0)}function getOptionsLabel(t){if(!t)return"";const e=[];return t.size&&e.push(`Size: ${t.size}`),t.color&&e.push(`Color: ${t.color}`),e.join(" • ")}function renderCart(){const t=getCart();if(cartItemsContainer.innerHTML="",!t.length)return cartEmptyState.style.display="flex",cartSummary.style.display="none",void(checkoutBtn.disabled=!0);cartEmptyState.style.display="none",cartSummary.style.display="block",checkoutBtn.disabled=!1,t.forEach((t,e)=>{const n=getOptionsLabel(t.options),a=getOptimizedImageUrl(t.image,160),r=getOptimizedImageSrcset(t.image,[110,160,220]),c=document.createElement("article");c.className="cart-item",c.dataset.index=e,c.innerHTML=`\n      <div class="cart-item-image">\n        <img\n          src="${a}"\n          srcset="${r}"\n          alt="${t.title}"\n          loading="lazy"\n          decoding="async"\n          width="110"\n          height="110"\n          sizes="110px"\n        />\n      </div>\n      <div class="cart-item-details">\n        <h3>${t.title}</h3>\n        ${n?`<p class="item-options">${n}</p>`:""}\n        <div class="cart-item-meta">\n          <span class="item-price">${formatCurrency(t.unitPrice||t.price)}</span>\n          <button type="button" class="remove-item-btn">Remove</button>\n        </div>\n      </div>\n      <div class="cart-item-quantity">\n        <button type="button" class="qty-btn" data-action="decrease">−</button>\n        <input type="text" value="${t.quantity}" readonly aria-label="Quantity" />\n        <button type="button" class="qty-btn" data-action="increase">+</button>\n      </div>\n    `,cartItemsContainer.appendChild(c)}),cartTotalAmount.textContent=formatCurrency(calculateCartTotal(t))}function updateItemQuantity(t,e){const n=getCart(),a=n[t];if(!a)return;const r=Math.max(1,a.quantity+e);a.quantity=r,saveCart(n),renderCart()}function removeItem(t){const e=getCart();e.splice(t,1),saveCart(e),renderCart()}cartItemsContainer.addEventListener("click",t=>{const e=t.target,n=e.closest(".cart-item");if(!n)return;const a=Number(n.dataset.index);if(e.classList.contains("qty-btn")){updateItemQuantity(a,"increase"===e.dataset.action?1:-1)}e.classList.contains("remove-item-btn")&&removeItem(a)}),checkoutBtn.addEventListener("click",()=>{getCart().length&&(window.location.href="checkout.html")}),window.addEventListener("DOMContentLoaded",()=>{updateCartBadge(),renderCart()});
